function emptyRows(message='—'){return ['Vocals','Drums','Bass','Other'].map(name=>`<div class="stem"><span class="stem-name">${name}</span><div class="wave-box pending"><span class="pending-text">${message}</span></div><button disabled aria-label="Solo ${name}">solo</button><button disabled aria-label="Mute ${name}">mute</button></div>`).join('');}
