function loadDemo(){selectedFile=null;$('#separate').disabled=true;$('#upload-state').textContent='';stop();offset=0;duration=12;buffers=makeDemo();render(defaults);$('#track-title').textContent='After hours';$('#track-type').textContent='ORIGINAL DEMO SESSION';$('#track-detail').textContent='Bass · drums · keys · lead';$('#play-label').textContent='Listen to the layers';$('#download').textContent='Download mix ↓';}
async function select(file){if(busy)return;if(!file)return;if(file.size>50*1024*1024){$('#upload-state').textContent='Please choose a recording smaller than 50 MB.';return;}$('#upload-state').textContent='Reading audio…';try{const b=await audio().decodeAudioData(await file.arrayBuffer());if(b.duration>600)throw Error('Please choose a recording shorter than 10 minutes.');stop();offset=0;buffers=[b];duration=b.duration;selectedFile=file;render(['Original']);$('#track-title').textContent=file.name.replace(/\.[^.]+$/,'');$('#track-type').textContent='YOUR RECORDING · LOCAL PREVIEW';$('#track-detail').textContent='Preview the original before separation';$('#play-label').textContent='Listen to your recording';$('#upload-state').textContent=`${file.name} · ${(file.size/1048576).toFixed(1)} MB · ${b.duration.toFixed(1)} seconds decoded.${b.duration < 30 ? ' This file is a short clip; upload the full recording if you expected a complete song.' : ''}`;$('#player').hidden=false;$('#file-name').textContent=file.name;window.dispatchEvent(new CustomEvent('recording-ready',{detail:{file,buffer:b}}));$('#separate').disabled=!backend||busy;$('#download').textContent='Download mix ↓';}catch(e){$('#upload-state').textContent=e.message.startsWith('Please')?e.message:'This audio format could not be decoded. Try MP3 or WAV.';}}
function wav(channels,rate){const n=channels[0].length,count=channels.length,b=new ArrayBuffer(44+n*count*2),v=new DataView(b);const str=(p,s)=>{for(let i=0;i<s.length;i++)v.setUint8(p+i,s.charCodeAt(i));};str(0,'RIFF');v.setUint32(4,36+n*count*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,count,true);v.setUint32(24,rate,true);v.setUint32(28,rate*count*2,true);v.setUint16(32,count*2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*count*2,true);for(let i=0;i<n;i++)for(let c=0;c<count;c++)v.setInt16(44+(i*count+c)*2,Math.max(-1,Math.min(1,channels[c][i]))*32767,true);return new Blob([b],{type:'audio/wav'});}
async function download(){if(!buffers.length)return;const length=Math.ceil(duration*44100),offline=new OfflineAudioContext(2,length,44100),any=tracks.some(t=>t.solo);buffers.forEach((b,i)=>{const s=offline.createBufferSource(),g=offline.createGain();s.buffer=b;g.gain.value=tracks[i].mute||(any&&!tracks[i].solo)?0:tracks[i].level;s.connect(g);g.connect(offline.destination);s.start();});const mixed=await offline.startRendering(),blob=wav([mixed.getChannelData(0),mixed.getChannelData(1)],44100),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='unlayer-mix.wav';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
