function separationProgress(stage,percent=null,failed=false){const box=$('#separation-progress'),bar=$('#separation-bar');box.hidden=false;box.classList.toggle('failed',failed);$('#separation-stage').textContent=stage;$('#separation-percent').textContent=Number.isFinite(percent)?`${Math.round(percent)}%`:'';bar.hidden=failed;if(Number.isFinite(percent))bar.value=percent;else bar.removeAttribute('value');}
